Wash_Tomato_and_Potato_and_egg_and_Cook_:
def Wash_Tomato_and_Potato_and_egg_and_Cook_Egg_Fry():
	# 0: Wash Tomato
	walk('Tomato')
	pickup('Tomato')
	walk('Faucet')
	toggleon('Faucet')
	assert('Tomato' in 'hand')
		else: walk('Tomato')
		else: pickup('Tomato')
		else: walk('Faucet')
	put('Tomato', 'SinkBasin')
	toggleoff('Faucet')
	assert('Tomato' in 'Hand')
		else: pickup('Tomato')
	walk('CounterTop')
	put('Tomato', 'CounterTop')
	# 1: Wash Potato
	walk('Potato')
	pickup('Potato')
	walk('Faucet')
	toggleon('Faucet')
	assert('Potato' in 'hand')
		else: walk('Potato')
		else: pickup('Potato')
		else: walk('Faucet')
	put('Potato', 'SinkBasin')
	toggleoff('Faucet')
	assert('Potato' in 'Hand')
		else: pickup('Potato')
	walk('CounterTop')
	put('Potato', 'CounterTop')
	# 2: Wash Egg
	walk('Egg')
	pickup('Egg')
	walk('Faucet')
	toggleon('Faucet')
	assert('Egg' in 'hand')
		else: walk('Egg')
		else: pickup('Egg')
		else: walk('Faucet')
	put('Egg', 'SinkBasin')
	toggleoff('Faucet')
	assert('Egg' in 'Hand')
		else: pickup('Egg')
	walk('CounterTop')
	put('Egg', 'CounterTop')
	# 3: Put the pan on the stoveburner
	assert('Pan' on 'StoveBurner')
		else: walk('Pan')
		else: pickup('Pan')
		else: walk('StoveBurner')
		else: put('Pan', 'StoveBurner')
	walk('StoveKnob')
	toggleon('StoveKnob')
	# 4: Start cook egg
	walk('Egg')
	pickup('Egg')
	walk('Pan')
	assert('Egg' in 'hand')
		else: walk('Egg')
		else: pickup('Egg')
		else: walk('Pan')
	assert(close to 'Pan') 
		else: walk('Pan') 
	put('Egg', 'Pan') 
	slice('Egg') 
	# 4: Turn off stove after cooking
	walk('StoveKnob') 
	toggleoff('StoveKnob') 
	# 5: Done
